      <!-- ══════════════════════════════════════════ HERO ══ -->
      <div class="tnd-hero">
        <div class="tnd-hero__top">
          <div class="tnd-hero__icon">
            <v-icon color="white" size="20">mdi-school-outline</v-icon>
          </div>
          <div class="tnd-hero__meta">
            <div class="tnd-hero__eyebrow">Training Need</div>
            <div class="tnd-hero__title">{{ need.name }}</div>
          </div>
          <v-btn icon dark small class="tnd-hero__close" @click="close">
            <v-icon size="20">mdi-close</v-icon>
          </v-btn>
        </div>

        <!-- ── summary pills ── -->
        <div class="tnd-hero__pills">
          <div class="tnd-pill">
            <v-icon size="12" class="tnd-pill__icon"
              >mdi-office-building-outline</v-icon
            >
