          </div>
          <div class="tnd-pill">
            <v-icon size="12" class="tnd-pill__icon">mdi-calendar-range</v-icon>
            {{ formatDate(need.startDate) }} — {{ formatDate(need.endDate) }}
          </div>
          <div class="tnd-pill">
            <v-icon size="12" class="tnd-pill__icon"
              >mdi-hospital-building</v-icon
            >
            {{ need.facilityIds.length }}
            {{ need.facilityIds.length === 1 ? "facility" : "facilities" }}
          </div>
        </div>
      </div>

      <!-- ══════════════════════════════════ BODY ══ -->
      <v-card-text class="tnd-body pa-0">
        <!-- ── Department ── -->
        <div class="tnd-section">
          <div class="tnd-row">
            <div class="tnd-field">
              <div class="tnd-field__label">
                <v-icon size="13" class="tnd-field__icon"
