          <div class="tnd-field__label mb-2">
            <v-icon size="13" class="tnd-field__icon"
              >mdi-account-group-outline</v-icon
            >
            Cadre{{ need.cadres.length !== 1 ? "s" : "" }}
          </div>
          <div class="tnd-chips">
            <v-chip
              v-for="c in need.cadres"
              :key="c.code"
              small
