<script>
export default {
  name: "TrainingNeedDetail",

  props: {
    value: {
      type: Boolean,
      default: false,
    },
    need: {
      type: Object,
      default: null,
    },
  },

  computed: {
    facilityNameList() {
      if (
        !this.need ||
        !this.need.facilityNames ||
        this.need.facilityNames === "—"
      )
        return [];
      return this.need.facilityNames.split(", ").filter(Boolean);
    },

    // Human-readable duration between start and end date.
    duration() {
      if (!this.need || !this.need.startDate || !this.need.endDate) return null;
      const start = new Date(this.need.startDate);
      const end = new Date(this.need.endDate);
      if (isNaN(start) || isNaN(end) || end < start) return null;
      const days = Math.round((end - start) / 86400000);
      if (days === 0) return "Same day";
      if (days < 7) return days + (days === 1 ? " day" : " days");
      const weeks = Math.round(days / 7);
      if (weeks < 5) return weeks + (weeks === 1 ? " week" : " weeks");
      const months = Math.round(days / 30.44);
      return months + (months === 1 ? " month" : " months");
    },
  },

  methods: {
    close() {
      this.$emit("input", false);
    },

    onEdit() {
      this.$emit("edit", this.need);
      this.close();
    },

    // Format YYYY-MM-DD → DD MMM YYYY; pass through anything else unchanged.
    formatDate(val) {
      if (!val) return "";
      const d = new Date(val);
      if (isNaN(d)) return val;
      return d.toLocaleDateString("en-GB", {
        day: "2-digit",
        month: "short",
        year: "numeric",
      });
    },
  },
};
</script>

